<script setup lang="ts">
import * as T from 'three'
import { OrbitControls } from 'three/addons/controls/OrbitControls.js'
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js'
import {HDRLoader} from 'three/addons/loaders/HDRLoader.js'
import {createEngineAudio} from '~/three/engineAudio'
import gsap from 'gsap'
import { createVehicle } from '~/three/vehicle'
import { loadVehicle } from '~/three/loadVehicle'
import {createScenery} from '~/three/scenery'
import {createAutomaticDrive} from '~/three/automaticDrive'
import {createCockpitLook} from '~/three/cockpitLook'
import {interiorDetails} from '~/data/finishes'
const props=defineProps<{drive?:boolean}>(),emit=defineEmits<{ready:[],progress:[number],speed:[number],telemetry:[{gear:number,rpm:number}],error:[string]}>()
const {t}=useLocale();const el=ref<HTMLDivElement>(),state=useAtelier();let renderer:T.WebGLRenderer,scene:T.Scene,camera:T.PerspectiveCamera,controls:OrbitControls,car:ReturnType<typeof createVehicle>,frame=0,pmrem:T.PMREMGenerator,env:T.Texture,world:any,rigid:any,rapier:any
let scenery:ReturnType<typeof createScenery>;const transmission=createAutomaticDrive(parseFloat(state.car.value.speed)||325),engineAudio=createEngineAudio();let stopped=false,angle=0,cam=0,paused=false;const keys=new Set<string>();const reduced=()=>!state.motion.value;let resize:ResizeObserver;let floor:T.Mesh,key:T.DirectionalLight,fill:T.PointLight,ambient:T.HemisphereLight,envTarget:T.WebGLRenderTarget
let look:ReturnType<typeof createCockpitLook>,cockpitActive=false,resizeFrame=0,transition:gsap.core.Timeline|undefined
let pointer:number|null=null,previousX=0,previousY=0
let landscape:T.DataTexture|undefined,landscapeTarget:T.WebGLRenderTarget|undefined,landscapeReady:Promise<void>|undefined
function applyPhotographicEnvironment(){if(!scene||!landscape)return;const outdoors=state.environment.value==='alpine';if(outdoors){scene.background=landscape;scene.environment=landscapeTarget!.texture;scene.backgroundIntensity=state.lighting.value==='Night'?.045:state.lighting.value==='Dark Room'?.15:state.lighting.value==='Sunset'?.7:.85;scene.backgroundRotation.y=.7;scene.environmentRotation.y=.7}else{scene.environment=env;scene.backgroundIntensity=1}}
function pointerDown(e:PointerEvent){if(!cockpitActive||pointer!==null)return;pointer=e.pointerId;previousX=e.clientX;previousY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}
function pointerMove(e:PointerEvent){if(e.pointerId!==pointer||!cockpitActive)return;look.turn(e.clientX-previousX,e.clientY-previousY);previousX=e.clientX;previousY=e.clientY}
function pointerUp(e:PointerEvent){if(e.pointerId===pointer){pointer=null;if(renderer.domElement.hasPointerCapture(e.pointerId))renderer.domElement.releasePointerCapture(e.pointerId)}}
function blur(){keys.clear();pointer=null}
function applyBackground(){if(!scene)return;scene.background=new T.Color(state.background.value);scene.fog=new T.Fog(state.background.value,18,65);(floor.material as T.MeshStandardMaterial).color.set(state.background.value).multiplyScalar(.28);scenery?.update(state.environment.value,state.lighting.value);applyPhotographicEnvironment();if(camera){camera.far=props.drive||state.environment.value!=='studio'?3200:160;camera.updateProjectionMatrix()}}
function applyLighting(){if(!key)return;const preset=state.lighting.value;key.intensity=preset==='Dark Room'?.7:preset==='Night'?1.2:preset==='Soft Day'?2.6:4;key.color.set(preset==='Sunset'?'#ffd4a0':'#f5ffe3');fill.color.set(preset==='Sunset'?'#ff9865':preset==='Night'?'#779cd9':'#c7f2f0');fill.intensity=preset==='Dark Room'?12:preset==='Night'?25:70;ambient.intensity=preset==='Dark Room'?.2:preset==='Night'?.3:preset==='Soft Day'?1.1:.7;scene.environmentIntensity=preset==='Dark Room'?.45:preset==='Night'?.65:1;scenery?.update(state.environment.value,state.lighting.value);applyPhotographicEnvironment()}
function applyConfiguration(){car.body.color.set(state.paint.value);car.leather.color.set(state.upholstery.value);car.white.emissiveIntensity=state.headlights.value?2:0;applyBackground();applyLighting()}
function reset(){rigid?.setTranslation({x:0,y:.58,z:0},true);rigid?.setLinvel({x:0,y:0,z:0},true);angle=0;transmission.reset();emit('speed',0);emit('telemetry',{gear:1,rpm:900})}
function keyboard(e:KeyboardEvent){if(['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const physical:Record<string,string>={KeyW:'w',KeyS:'s',KeyA:'a',KeyD:'d',KeyR:'r',KeyC:'c',Space:' '};keys.add(physical[e.code]||e.key.toLowerCase());if(e.key.toLowerCase()==='r')reset();if(e.key.toLowerCase()==='c')cam=(cam+1)%3;if(e.key==='Escape')paused=!paused;if(state.engine.value)engineAudio.start()}
function release(e:KeyboardEvent){const physical:Record<string,string>={KeyW:'w',KeyS:'s',KeyA:'a',KeyD:'d',Space:' '};keys.delete(physical[e.code]||e.key.toLowerCase())}
onMounted(async()=>{try{
 await nextTick();if(!el.value)throw new Error('Scene container is not mounted. Please retry.');
 emit('progress',10);scene=new T.Scene();scene.background=new T.Color('#101313');scene.fog=new T.Fog('#101313',18,65)
 renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,{Low:.75,Medium:1,High:1.8,Ultra:2}[state.quality.value]||1));renderer.shadowMap.enabled=state.shadows.value;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.85;el.value!.appendChild(renderer.domElement)
 camera=new T.PerspectiveCamera(36,1,.05,160);camera.position.set(-5.7,2.35,6.3);controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.65,0);controls.enableDamping=true;controls.minDistance=3;controls.maxDistance=13;controls.maxPolarAngle=Math.PI/2-.03;controls.minPolarAngle=.25;controls.enablePan=false;controls.enabled=!props.drive
 look=createCockpitLook(camera);renderer.domElement.addEventListener('pointerdown',pointerDown);renderer.domElement.addEventListener('pointermove',pointerMove);renderer.domElement.addEventListener('pointerup',pointerUp);renderer.domElement.addEventListener('pointercancel',pointerUp);window.addEventListener('blur',blur)
 emit('progress',35);pmrem=new T.PMREMGenerator(renderer);const room=new RoomEnvironment();envTarget=pmrem.fromScene(room,.04);env=envTarget.texture;scene.environment=env;room.dispose();landscapeReady=new HDRLoader().loadAsync('/models/alps_field_2k.hdr').then(texture=>{if(stopped){texture.dispose();return}landscape=texture;texture.mapping=T.EquirectangularReflectionMapping;landscapeTarget=pmrem.fromEquirectangular(texture);applyPhotographicEnvironment()}).catch(()=>{})
 ambient=new T.HemisphereLight('#dcdfd2','#121712',.7);scene.add(ambient);key=new T.DirectionalLight('#f5ffe3',4);key.position.set(-3,7,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-7;key.shadow.camera.right=7;key.shadow.camera.top=7;key.shadow.camera.bottom=-7;key.shadow.bias=-.001;scene.add(key,key.target)
 fill=new T.PointLight('#c7f2f0',70,25);fill.position.set(5,3,-4);scene.add(fill)
 floor=new T.Mesh(new T.PlaneGeometry(250,250),new T.MeshStandardMaterial({color:'#060807',metalness:0,roughness:1,envMapIntensity:.01}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor)
 scenery=createScenery(scene,!!props.drive);if(!props.drive){for(const radius of [3.7,3.73,4.4]){const ring=new T.Mesh(new T.RingGeometry(radius,radius+.008,128),new T.MeshBasicMaterial({color:'#475143',transparent:true,opacity:.3,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.003;scene.add(ring)}}
 emit('progress',65);car=await loadVehicle(state.car.value.shape,n=>emit('progress',n));if(stopped){car.dispose();return}applyConfiguration();scene.add(car.root)
 if(props.drive){rapier=(await import('@dimforge/rapier3d-compat')).default;await rapier.init();if(stopped)return;world=new rapier.World({x:0,y:-9.81,z:0});world.createCollider(rapier.ColliderDesc.cuboid(1100,.1,250).setTranslation(0,-.1,0).setFriction(0));rigid=world.createRigidBody(rapier.RigidBodyDesc.dynamic().setTranslation(0,.58,0).enabledRotations(false,true,false).setLinearDamping(0));world.createCollider(rapier.ColliderDesc.cuboid(2.3,.45,.95).setMass(1500).setFriction(0),rigid)
 window.addEventListener('keydown',keyboard);window.addEventListener('keyup',release)
 }else if(state.motion.value){camera.position.set(-3.4,1.3,4);gsap.to(camera.position,{x:-5.7,y:2.35,z:6.3,duration:2.5,ease:'power2.inOut'})}
 function sizeScene(){if(stopped||!el.value)return;const w=el.value.clientWidth,h=el.value.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=state.interior.value?76:camera.aspect<.8?65:36;camera.updateProjectionMatrix()}
 resize=new ResizeObserver(()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(sizeScene)});resize.observe(el.value!);sizeScene()
 emit('progress',90);await landscapeReady;if(stopped)return;renderer.compile(scene,camera);emit('progress',100);emit('ready')
 let last=performance.now(),count=0,sum=0
 function tick(now:number){if(stopped)return;frame=requestAnimationFrame(tick);const dt=Math.min((now-last)/1000,.04);last=now
  if(props.drive&&world&&!paused){const velocity=rigid.linvel();const forward=new T.Vector3(-Math.cos(angle),0,Math.sin(angle));let speed=velocity.x*forward.x+velocity.z*forward.z;const throttle=keys.has('w')||keys.has('arrowup'),braking=keys.has('s')||keys.has('arrowdown');const driveState=transmission.step(dt,speed,throttle,braking,keys.has(' '));speed=driveState.speed;emit('telemetry',{gear:driveState.gear,rpm:driveState.rpm});const steering=(keys.has('a')||keys.has('arrowleft')?1:0)-(keys.has('d')||keys.has('arrowright')?1:0);angle+=steering*dt*Math.min(Math.abs(speed)*.09,1.25)*Math.sign(speed);rigid.setLinvel({x:forward.x*speed,y:velocity.y,z:forward.z*speed},true);rigid.setRotation({x:0,y:Math.sin(angle/2),z:0,w:Math.cos(angle/2)},true);world.timestep=dt;world.step();const p=rigid.translation();if(Math.abs(p.x)>900){rigid.setTranslation({x:-p.x,y:p.y,z:p.z},true);camera.position.x=-camera.position.x}if(Math.abs(p.z)>90)reset();car.root.position.set(p.x,p.y-.48,p.z);car.root.rotation.y=angle;key.position.set(p.x-3,p.y+7,p.z+4);key.target.position.set(p.x,p.y,p.z);car.wheels.forEach(w=>{w.rotation.z+=speed*dt/.36});engineAudio.update(driveState.rpm,throttle,state.volume.value,state.engine.value,speed);emit('speed',Math.round(Math.abs(speed)*3.6));const offset=cam===0?new T.Vector3(7,3,4):cam===1?new T.Vector3(-1.6,1.05,0):new T.Vector3(0,9,10);offset.applyAxisAngle(new T.Vector3(0,1,0),angle);camera.position.lerp(car.root.position.clone().add(offset),.07);camera.lookAt(car.root.position.clone().add(new T.Vector3(cam===1?-6:0,.8,0)))}else if(!props.drive&&controls.enabled)controls.update()
  if(props.drive&&paused)engineAudio.update(900,false,state.volume.value,false);if(cockpitActive)look.apply();renderer.render(scene,camera);sum+=dt;count++;if(count===120){if(sum>4&&state.quality.value==='High'){renderer.setPixelRatio(1)}sum=0;count=0}
 }frame=requestAnimationFrame(tick)
 }catch(e){emit('error',e instanceof Error?e.message:'WebGL unavailable')}})
watch(()=>state.engine.value,v=>{if(props.drive&&v)engineAudio.start();if(!v)engineAudio.update(900,false,state.volume.value,false)},{flush:'sync'})
watch(()=>state.paint.value,v=>car?.body.color.set(v));watch(()=>state.upholstery.value,v=>car?.leather.color.set(v));watch(()=>state.headlights.value,v=>{if(car)car.white.emissiveIntensity=v?2:0})
watch(()=>state.doors.value,v=>{car?.doors.forEach((d,i)=>gsap.to(d.rotation,{y:state.car.value.shape===8&&v?(i===0?1.12:-1.12):0,z:state.car.value.shape!==8&&v?-1.05:0,x:state.car.value.shape!==8&&v?(i===0?-.15:.15):0,duration:reduced()?.01:1.2,ease:'power2.inOut'}))})
watch(()=>state.interior.value,v=>{
 if(stopped||!camera||props.drive)return;transition?.kill();gsap.killTweensOf(camera.position);cockpitActive=false;pointer=null;controls.enabled=false
 const target=new T.Vector3(-.55,.97,.35),begin=camera.position.clone(),progress={value:0}
 transition=gsap.timeline({onComplete(){if(v){look.reset();const selected=interiorDetails.find(d=>d.id===state.detail.value);if(selected)look.aim(new T.Vector3(...selected.point as [number,number,number]));cockpitActive=true}else{controls.target.set(0,.65,0);controls.minDistance=3;controls.maxDistance=13;controls.enabled=true}}})
 if(v){
  state.doors.value=true
  const approach=new T.Vector3(-.13,1.18,1.75),entry=new T.CubicBezierCurve3(approach,new T.Vector3(-.22,1.17,1.15),new T.Vector3(-.18,1.12,.54),look.anchor.clone())
  transition.to(camera.position,{x:approach.x,y:approach.y,z:approach.z,duration:reduced()?.01:.85,ease:'power2.inOut',onUpdate(){camera.lookAt(target)}},0)
  transition.to(progress,{value:1,duration:reduced()?.01:1.45,ease:'sine.inOut',onUpdate(){camera.position.copy(entry.getPoint(progress.value));camera.lookAt(target);camera.rotateZ(Math.sin(progress.value*Math.PI)*.055)}},reduced()?0:.85)
  transition.to(camera,{fov:76,duration:reduced()?.01:1.45,ease:'sine.inOut',onUpdate(){camera.updateProjectionMatrix()}},reduced()?0:.85)
 }else{const exit=new T.CubicBezierCurve3(begin,new T.Vector3(-.05,1.28,1.3),new T.Vector3(-2.4,1.9,4.1),new T.Vector3(-5.7,2.35,6.3));transition.to(progress,{value:1,duration:reduced()?.01:1.7,ease:'power2.inOut',onUpdate(){camera.position.copy(exit.getPoint(progress.value));camera.lookAt(0,.65,0)}},0).to(camera,{fov:camera.aspect<.8?65:36,duration:reduced()?.01:1.5,onUpdate(){camera.updateProjectionMatrix()}},0)}
 if(car)car.glass.visible=!v
})
watch(()=>state.detail.value,id=>{if(!cockpitActive)return;const detail=interiorDetails.find(d=>d.id===id);if(detail)look.aim(new T.Vector3(...detail.point as [number,number,number]));gsap.to(camera,{fov:id==='pedals'?54:id==='instruments'?48:id==='console'?58:76,duration:reduced()?.01:.6,ease:'sine.inOut',onUpdate(){camera.updateProjectionMatrix()}})})
watch(()=>state.focus.value,id=>{if(!id||state.interior.value||!camera||props.drive)return;const presets:Record<string,{position:number[],target:number[]}>= {front:{position:[-5,1.5,1.7],target:[-.6,.6,0]},side:{position:[-.3,1.65,7],target:[0,.6,0]},rear:{position:[5,1.7,3.8],target:[1,.65,0]},wheel:{position:[-1.7,.7,2.2],target:[-1.2,.37,.85]}};const preset=presets[id];if(!preset)return;gsap.killTweensOf(camera.position);controls.enabled=false;controls.minDistance=id==='wheel'?.8:3;controls.target.set(...preset.target as [number,number,number]);gsap.to(camera.position,{x:preset.position[0],y:preset.position[1],z:preset.position[2],duration:reduced()?.01:.9,onUpdate(){camera.lookAt(controls.target)},onComplete(){controls.enabled=true}})})
watch(()=>state.environment.value,applyBackground);watch(()=>state.background.value,applyBackground);watch(()=>state.lighting.value,applyLighting)
watch(()=>state.quality.value,v=>{if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,{Low:.75,Medium:1,High:1.8,Ultra:2}[v]||1));key.shadow.mapSize.set(v==='Low'?512:2048,v==='Low'?512:2048);key.shadow.map?.dispose();key.shadow.map=null}})
watch(()=>state.shadows.value,v=>{if(renderer)renderer.shadowMap.enabled=v})
watch(()=>state.car.value.id,()=>{if(!scene||!car)return;const old=car;gsap.to(old.root.scale,{x:.01,y:.01,z:.01,duration:.3,async onComplete(){scene.remove(old.root);old.dispose();try{const loaded=await loadVehicle(state.car.value.shape,n=>emit('progress',n));if(stopped){loaded.dispose();return}car=loaded;applyConfiguration();scene.add(car.root);car.root.scale.setScalar(.01);gsap.to(car.root.scale,{x:1,y:1,z:1,duration:.7})}catch(e){emit('error','Vehicle could not load. Please retry.')}}})})
onBeforeUnmount(()=>{stopped=true;engineAudio.dispose();cancelAnimationFrame(frame);cancelAnimationFrame(resizeFrame);transition?.kill();resize?.disconnect();window.removeEventListener('keydown',keyboard);window.removeEventListener('keyup',release);window.removeEventListener('blur',blur);world?.free();controls?.dispose();if(renderer){renderer.domElement.removeEventListener('pointerdown',pointerDown);renderer.domElement.removeEventListener('pointermove',pointerMove);renderer.domElement.removeEventListener('pointerup',pointerUp);renderer.domElement.removeEventListener('pointercancel',pointerUp)}gsap.killTweensOf(camera?.position);if(car){car.doors.forEach(d=>gsap.killTweensOf(d.rotation));scene.remove(car.root);car.dispose()}scene?.traverse(o=>{if(o instanceof T.Mesh){o.geometry.dispose();if(o instanceof T.InstancedMesh)o.dispose();(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>{for(const value of Object.values(m))if(value instanceof T.Texture)value.dispose();m.dispose()})}});landscape?.dispose();landscapeTarget?.dispose();envTarget?.dispose();pmrem?.dispose();renderer?.dispose()})
defineExpose({reset,cycleCamera(){cam=(cam+1)%3},setKey(key:string,down:boolean){down?keys.add(key):keys.delete(key);if(down&&state.engine.value)engineAudio.start()}})
</script>
<template><div ref="el" class="vehicle-canvas" tabindex="0" :aria-label="t('Интерактивная 3D-модель. Перетаскивайте для поворота, используйте колесо для масштаба.','Interactive three-dimensional vehicle. Drag to rotate, scroll to zoom.')" /></template>



